function picker(kind,label,selected,optional=false){return `<div class="field combo-field"><label for="${kind}">${label}${optional?'<span>необязательно</span>':' <b class="required">*</b>'}</label><div class="combo-control"><input id="${kind}" ${kind==='route'?'inputmode="numeric"':''} role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="${kind}-options" autocomplete="off" placeholder="${kind==='route'?'Введите номер маршрута':optional?'Без прицепа':kind==='driver'?'Выберите водителя':'Выберите транспортное средство'}" ${optional?'':'required'}><input type="hidden" name="${kind}Id"><button type="button" class="combo-toggle" aria-label="Открыть список: ${label}" tabindex="-1"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="m6 9 6 6 6-6"/></svg></button></div><div id="${kind}-options" class="combo-options" role="listbox" aria-label="${label}" popover="manual"></div></div>`;}
