  document.querySelector('#catalog-search').oninput=e=>{state.query=e.target.value;clearTimeout(catalogSearchTimer);viewport.scrollTop=0;void collection.reset(state.query,{load:false});catalogSearchTimer=setTimeout(()=>void collection.loadMore(),350);};
