const logNames={card_access_denied:'Нет доступа к карточке',worker_started:'Процесс мониторинга запущен',no_plans:'Нет активных планов',poll_started:'Начало проверки',request_started:'Запрос отправляется',response_received:'Ответ WB',request_completed:'Запрос завершён',request_failed:'Ошибка запроса',request_cancelled:'Запрос отменён',poll_completed:'Проверка завершена',poll_failed:'Ошибка проверки',snapshot_saved:'Ответ списка сохранён',acceptance_request:'Отправка принятия',acceptance_success:'Взята в работу',acceptance_error:'Ошибка принятия',curl_preview:'cURL — только текст'};
