let botStatusLoading=false;
async function refreshBotStatus(){await updateHeaderBot();}
boot();


let botMutating=false,botEpoch=0,headerLoading=false;
function applyBotSnapshot(data){
 if(data.settings){state.bot=data;const toggle=document.querySelector('#bot-enabled');if(toggle)toggle.checked=data.settings.enabled;const live=document.querySelector('#bot-live');if(live&&!state.botFormDirty)live.checked=data.settings.acceptanceEnabled===true;}
 state.botPublic={enabled:data.settings?.enabled??data.enabled,runtime:data.runtime};
 paintHeaderBot();if(state.view==='bot'){updateBotSettingsLock();renderBotRuntime();}if(state.view==='requests')void refreshRequestState();
}
function paintHeaderBot(){
 const box=document.querySelector('#header-bot');if(!box||!state.botPublic)return;
 const data=state.botPublic,on=data.enabled;
 const tone=on?'on':'off';
 const title=on?'Бот запущен':'Бот остановлен';
 box.innerHTML=`<div class="bot-header-status is-${tone}" role="status" aria-live="polite"><span class="bot-status-dot" aria-hidden="true"></span><div><strong>${esc(title)}</strong></div>${['admin','super_admin'].includes(state.user.role)?`<button class="bot-power" id="header-bot-toggle" ${botMutating?'disabled':''} title="${on?'Выключить':'Включить'} бота" aria-label="${on?'Выключить':'Включить'} бота">${icon(on?'pause':'play')}</button>`:''}</div>`;
 const button=document.querySelector('#header-bot-toggle');if(button)button.onclick=()=>void setBotEnabled(!on);
}
async function setBotEnabled(enabled){
 if(enabled&&state.view==='bot'&&state.botFormDirty){toast('Сначала сохраните настройки бота.','error');return;}
 if(botMutating)return;botMutating=true;botEpoch++;paintHeaderBot();
 const toggle=document.querySelector('#bot-enabled');if(toggle)toggle.disabled=true;
 try{const current=await api('/api/bot/settings');applyBotSnapshot(await api('/api/bot/settings',{method:'POST',data:{...current.settings,enabled,scheduleEnabled:false,token:''}}));toast(enabled?'Мониторинг включён':'Мониторинг выключен');}
 catch(error){if(toggle)toggle.checked=state.bot?.settings.enabled||false;toast(error.message);}
 finally{botMutating=false;if(toggle)toggle.disabled=false;paintHeaderBot();}
}
async function updateHeaderBot(){
 if(!state.user||headerLoading||botMutating)return;headerLoading=true;const epoch=botEpoch;
 try{const data=await api(['admin','super_admin'].includes(state.user.role)?'/api/bot/status':'/api/bot/public-status');if(epoch===botEpoch&&!botMutating)applyBotSnapshot(data);}
 catch{const box=document.querySelector('#header-bot');if(box)box.innerHTML='<span class="bot-header-status is-error">Не удалось обновить статус</span>';}
 finally{headerLoading=false;}
}
setInterval(()=>{if(!document.hidden)void updateHeaderBot();},5000);
let monitorTable=null,monitorTableReady=false,monitorTableRows=[];
function renderMonitorTable(element){
  if(!Array.isArray(state.bot.logs)){element.innerHTML='<div class="error-box">Обновите сервер портала: он не передаёт журнал.</div>';return;}
  monitorTableRows=state.bot.logs.map(e=>{const p=e.payload;return{id:e.id,time:monitorTime(e.created_at),event:logNames[e.kind]||e.kind,routes:(p.routes||[p.routeId]).filter(Boolean).join(', ')||'—',http:p.httpStatus||'',duration:p.durationMs??'',result:logSummary(e),kind:e.kind,curl:p.curl||''};});
  if(monitorTable&&monitorTable.element===element){if(monitorTableReady)void monitorTable.replaceData(monitorTableRows);return;}
  monitorTable?.destroy();monitorTableReady=false;element.innerHTML='';
  monitorTable=new Tabulator(element,{data:monitorTableRows,index:'id',layout:'fitColumns',columnDefaults:{vertAlign:'middle',headerFilterPlaceholder:'Поиск…'},height:480,placeholder:'Записей пока нет. Они появятся после начала проверки.',pagination:true,paginationSize:15,paginationSizeSelector:[15,30,100],initialSort:[{column:'id',dir:'desc'}],locale:'ru',langs:{ru:{pagination:{first:'Первая',last:'Последняя',prev:'Назад',next:'Далее',page_size:'Строк',counter:{showing:'Показано',of:'из',rows:'записей',pages:'страниц'}}}},columns:[
    {field:'id',visible:false},
    {title:'Время',field:'time',width:175,formatter:'plaintext'},
    {title:'Событие',field:'event',width:190,headerFilter:'input',formatter:'plaintext'},
    {title:'Маршруты',field:'routes',width:160,headerFilter:'input',formatter:'plaintext'},
    {title:'HTTP',field:'http',width:80,headerFilter:'input',formatter:'plaintext'},
    {title:'мс',field:'duration',width:70,sorter:'number',formatter:'plaintext'},
    {title:'Результат',field:'result',minWidth:220,formatter:cell=>resultElement(cell.getRow().getData().kind,cell.getValue())},
    {title:'cURL',field:'curl',width:100,headerSort:false,formatter:cell=>{if(!cell.getValue())return '';const button=document.createElement('button');button.className='grid-action';button.title='Открыть cURL';button.setAttribute('aria-label','Открыть cURL');button.innerHTML=icon('code');button.onclick=()=>showCurlPreview(cell.getValue());return button;}}
  ]});
  monitorTable.on('tableBuilt',()=>{monitorTableReady=true;void monitorTable.replaceData(monitorTableRows);});
}

function acceptanceMarkup(id){const outcome=state.bot.outcomes?.find(e=>e.id===id);if(!outcome)return '<span class="outcome-neutral">— Запрос не отправлялся</span>';return '<span class="outcome-text"><b class="'+(outcome.kind==='acceptance_success'?'outcome-ok':'outcome-error')+'">'+(outcome.kind==='acceptance_success'?'✓':'✕')+'</b><span class="outcome-label">'+esc(outcome.kind==='acceptance_success'?'Взята в работу':'Ошибка принятия')+'</span></span><small class="outcome-description">'+esc(outcome.payload.message)+'</small>';}
function resultElement(kind,text){const box=document.createElement('div');box.className='outcome-text';if(['acceptance_success','acceptance_error','request_failed','poll_failed'].includes(kind)){const mark=document.createElement('b');mark.className=kind==='acceptance_success'?'outcome-ok':'outcome-error';mark.textContent=kind==='acceptance_success'?'✓':'✕';mark.setAttribute('aria-label',kind==='acceptance_success'?'Успех':'Ошибка');box.append(mark);}const label=document.createElement('span');label.textContent=text;box.append(label);return box;}

function updateMobileNavViewport(){const view=window.visualViewport;const bottom=view?Math.max(0,window.innerHeight-view.height-view.offsetTop):0;document.documentElement.style.setProperty('--mobile-nav-bottom',bottom+'px');}
window.visualViewport?.addEventListener('resize',updateMobileNavViewport);window.visualViewport?.addEventListener('scroll',updateMobileNavViewport);window.addEventListener('resize',updateMobileNavViewport);updateMobileNavViewport();
